        Environment.GetEnvironmentVariable("EVAL_USE_REAL_JUDGE") == "1";

    public static bool UseFoundrySafety =>
        Environment.GetEnvironmentVariable("EVAL_USE_FOUNDRY_SAFETY") == "1";

