namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureChatCompletionsClient("chat").AddChatClient("chat") at AppHost.cs:2
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        builder.Services.AddAzureChatCompletionsClient("chat").AddChatClient("chat");
        var host = builder.Build();
        try
        {
            return host.Services.GetRequiredService<IChatClient>();
        }
        catch (InvalidOperationException ex)
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration (AddAzureChatCompletionsClient) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost populates this at " +
                "runtime, but `dotnet test` runs standalone. Wire one of:\n" +
                "  # Key-based auth (only if the resource has it enabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential — works when key auth is disabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).\n" +
                "Get the exact endpoint from `azd env get-values` or " +
                "`az cognitiveservices account show -n <name> -g <rg> --query properties.endpoints`.",
                ex);
        }
    }
}

namespace MyApp.Evals.Tests;

internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMessage = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var response = new ChatResponse(new ChatMessage(ChatRole.Assistant,
            $"[Stub] Echoing: {userMessage}"))
        {
            ModelId = "stub",
            Usage = new UsageDetails { InputTokenCount = 10, OutputTokenCount = 20 },
        };
        return Task.FromResult(response);
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        throw new NotSupportedException("Streaming not supported by StubChatClient.");
    }

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

using System.Text.Json;

namespace MyApp.Evals.Tests;

[TestClass]
public sealed class QualityTests
{
    private static ReportingConfiguration s_reporting = null!;

    [ClassInitialize]
    public static void Init(TestContext _) =>
        s_reporting = ReportingConfig.ForQuality();

    public static IEnumerable<object[]> Golden() =>
        GoldenLoader.Load().Select(g => new object[] { g });

    [TestMethod]
    [DynamicData(nameof(Golden), DynamicDataSourceType.Method)]
    public async Task Evaluate(GoldenItem g)
    {
        var scenarioName = $"{nameof(QualityTests)}.{g.Id}";
        await using var run = await s_reporting.CreateScenarioRunAsync(scenarioName);

        var agent = string.IsNullOrEmpty(
            Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME"))
                ? run.ChatConfiguration!.ChatClient
                : Wire.ResolveAgentClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, RubricLoader.SystemPrompt()),
            new(ChatRole.User, g.UserMessage),
        };
        var response = await agent.GetResponseAsync(messages);

        var contexts = new List<EvaluationContext>();
        if (!string.IsNullOrEmpty(g.ReferenceResponse))
        {
            contexts.Add(new BLEUEvaluatorContext(new[] { g.ReferenceResponse }));
            contexts.Add(new GLEUEvaluatorContext(new[] { g.ReferenceResponse }));
            contexts.Add(new F1EvaluatorContext(g.ReferenceResponse));
            contexts.Add(new EquivalenceEvaluatorContext(g.ReferenceResponse));
            contexts.Add(new CompletenessEvaluatorContext(g.ReferenceResponse));
        }
        if (!string.IsNullOrEmpty(g.Context))
            contexts.Add(new GroundednessEvaluatorContext(g.Context));

        await run.EvaluateAsync(messages, response, contexts);
    }
}

public sealed record GoldenItem(
    string Id,
    string UserMessage,
    string? ReferenceResponse,
    string? Context,
    string[]? ExpectedTraits,
    string[]? ExpectedToolCalls)
{
    public override string ToString() => Id;
}

internal static class GoldenLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<GoldenItem> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");
        var doc = JsonDocument.Parse(File.ReadAllText(path));
        var scenarios = doc.RootElement.GetProperty("scenarios");
        return JsonSerializer.Deserialize<List<GoldenItem>>(scenarios.GetRawText(), s_options) ?? new();
    }
}

internal static class RubricLoader
{
    public static string SystemPrompt()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");
        return File.Exists(path) ? File.ReadAllText(path) : "You are a helpful assistant.";
    }
}

