using System.Diagnostics;
using System.Text.Json;

namespace MyApp.Evals.Tests;

[TestClass]
public sealed class TelemetryTests
{
    private static readonly List<TelemetryRecord> s_records = new();

    public static IEnumerable<object[]> Inputs() =>
        InputsLoader.Load().Select(i => new object[] { i });

    [TestMethod]
    [DynamicData(nameof(Inputs), DynamicDataSourceType.Method)]
    public async Task Capture(TelemetryInput input)
    {
        var inner = Wire.ResolveAgentClient();

        var messages = new List<ChatMessage> { new(ChatRole.User, input.Text) };
        var sw = Stopwatch.StartNew();
        var response = await inner.GetResponseAsync(messages);
        sw.Stop();

        var record = new TelemetryRecord(
            AgentName: input.Agent,
            Model: response.ModelId ?? "unknown",
            InputTokens: response.Usage?.InputTokenCount ?? 0,
            OutputTokens: response.Usage?.OutputTokenCount ?? 0,
            LatencyMs: sw.ElapsedMilliseconds);

        lock (s_records) { s_records.Add(record); }
    }

    [ClassCleanup]
    public static void WriteReports()
    {
        var outDir = Path.Combine(
            RepoRoot.Find(), ".copilot", "perf-reports", "evals", EvalEnv.ReportFolder);
        Directory.CreateDirectory(outDir);

        var json = JsonSerializer.Serialize(s_records, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(Path.Combine(outDir, "telemetry.json"), json);

        var md = "# Telemetry\n\n| Agent | Model | Input Tokens | Output Tokens | Latency (ms) |\n|-------|-------|-------------|--------------|---------------|\n";
        foreach (var r in s_records)
            md += $"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} |\n";
        File.WriteAllText(Path.Combine(outDir, "telemetry.md"), md);

        Console.WriteLine($"Telemetry report: {outDir}/telemetry.md");
    }
}

public sealed record TelemetryInput(string Agent, string Text)
{
    public override string ToString() => $"{Agent}: {Text[..Math.Min(30, Text.Length)]}";
}

public sealed record TelemetryRecord(
    string AgentName,
    string Model,
    int InputTokens,
    int OutputTokens,
    long LatencyMs);

internal static class InputsLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<TelemetryInput> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "inputs.json");
        return JsonSerializer.Deserialize<List<TelemetryInput>>(
            File.ReadAllText(path), s_options) ?? new();
    }
}

