namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureChatCompletionsClient("chat").AddChatClient("chat") at AppHost.cs:2
    ///
    /// NOTE: The eval project does not reference the Aspire hosting packages directly.
    /// Wire the connection string via user-secrets so the MEAI client resolves it.
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        var connectionString = builder.Configuration.GetConnectionString("chat");
        if (string.IsNullOrEmpty(connectionString))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but ConnectionStrings:chat is not configured. " +
                "The app uses AddAzureChatCompletionsClient(\"chat\") which reads from " +
                "the Aspire AppHost at runtime. For standalone `dotnet test`, wire:\n" +
                "  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" " +
                "--project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).");
        }

        // Use the OpenAI SDK with the connection string endpoint
        builder.Services.AddChatClient(sp =>
            new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(connectionString.Split(';')
                    .FirstOrDefault(s => s.StartsWith("Endpoint=", StringComparison.OrdinalIgnoreCase))
                    ?.Substring("Endpoint=".Length) ?? connectionString),
                new Azure.AzureKeyCredential("placeholder"))
            .AsChatClient("chat"));

        var host = builder.Build();
        return host.Services.GetRequiredService<IChatClient>();
    }
}

